<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Activity,ArrowUpRight,Check,ChevronRight,Code2,Database,GitBranch,KeyRound,Layers3,LogOut,Plus,Radio,RefreshCw,Search,Send,Settings2,ShieldCheck,Terminal,Webhook,X} from '@lucide/vue'
import {request,pretty,statusTone} from './api'
const route=useRoute(),router=useRouter()
const page=computed(()=>String(route.params.page||'overview'))
const nav=[{id:'overview',label:'运行概览',icon:Activity},{id:'sources',label:'消息源',icon:Radio},{id:'routes',label:'转发规则',icon:GitBranch},{id:'endpoints',label:'Webhook 目标',icon:Webhook},{id:'deliveries',label:'投递记录',icon:Layers3},{id:'debug',label:'请求调试',icon:Code2},{id:'credentials',label:'凭证管理',icon:KeyRound},{id:'audit',label:'操作审计',icon:ShieldCheck}]
const title=computed(()=>nav.find(n=>n.id===page.value)?.label||'运行概览')
const descriptions:Record<string,string>={overview:'从消息接入到外部投递，每一步都清晰可见。',sources:'独立订阅消息，保持原业务消费进度隔离。',endpoints:'定义目标接口的请求、签名与成功判定。',routes:'将消息源与目标连接，按条件独立转发。',deliveries:'检查每次投递的状态，追踪重试并补投。',debug:'使用样例消息预览最终请求，不发送外部请求。',credentials:'凭证加密存储，保存后仅显示名称和引用。',audit:'查询配置变更、取消与重放操作。'}
const authed=ref(false),checking=ref(true),token=ref(''),error=ref(''),notice=ref(''),loading=ref(false)
const sources=ref<any[]>([]),endpoints=ref<any[]>([]),routes=ref<any[]>([]),deliveries=ref<any[]>([]),credentials=ref<any[]>([]),audit=ref<any[]>([]),stats=ref<Record<string,number>>({}),states=ref<Record<string,any>>({})
const query=ref(''),editor=ref(false),editID=ref(''),json=ref(''),saving=ref(false),attempts=ref<any[]|null>(null),selectedID=ref(''),cursor=ref('')
const inject=ref(''),sample=ref('{"order_id":"ORD-20261110","amount":"128.50"}'),debugEndpoint=ref(''),preview=ref(''),credName=ref(''),credData=ref('{"secret":""}')
const prefix=location.pathname.split('/').filter(Boolean)[0]||'relay'
const list=computed(()=>page.value==='sources'?sources.value:page.value==='endpoints'?endpoints.value:routes.value)
const filtered=computed(()=>list.value.filter(x=>pretty(x).toLowerCase().includes(query.value.toLowerCase())))
const pending=computed(()=>['PENDING','RETRY_WAIT','SENDING'].reduce((n,k)=>n+(stats.value[k]||0),0))
const total=computed(()=>Object.values(stats.value).reduce((a,b)=>a+b,0))
const success=computed(()=>{const completed=(stats.value.SUCCEEDED||0)+(stats.value.DEAD||0);return completed?`${(((stats.value.SUCCEEDED||0)/completed)*100).toFixed(1)}%`:'—'})
async function load(){if(!authed.value)return;loading.value=true;try{const result=await Promise.all([request('/sources'),request('/endpoints'),request('/routes'),request('/deliveries'+(cursor.value?`?before=${cursor.value}`:'')),request('/stats'),request('/source-status'),request('/credentials')]);[sources.value,endpoints.value,routes.value,deliveries.value,stats.value,states.value,credentials.value]=result;if(page.value==='audit')audit.value=await request('/audit')}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function login(){error.value='';try{await request('/sessions','POST',{token:token.value});token.value='';authed.value=true;await load()}catch(e:any){error.value=e.message}}
async function logout(){try{await request('/sessions','DELETE')}finally{authed.value=false}}
function flash(message:string){notice.value=message;setTimeout(()=>notice.value='',4000)}
function newConfig(){editID.value='';let v:any
 if(page.value==='sources')v={name:'订单消息',type:'kafka',enabled:false,brokers:['localhost:9092'],topics:['orders'],group:'relay.orders',start:'latest'}
 else if(page.value==='endpoints')v={name:'订单回调',enabled:false,url:'https://example.com/hooks/orders',method:'POST',headers:{'Content-Type':'application/json'},body_mode:'raw',auth:{type:'none',credential_ref:''},timeout_ms:10000,concurrency:16,rps:50,max_attempts:8,success_statuses:[200,201,202,204],allow_private:false}
 else v={name:'订单转发',enabled:false,source_id:sources.value[0]?.id||'',endpoint_ids:endpoints.value[0]?[endpoints.value[0].id]:[]}
 json.value=pretty(v);editor.value=true}
function edit(v:any){editID.value=v.id;json.value=pretty(v);editor.value=true}
async function save(){saving.value=true;error.value='';try{const v=JSON.parse(json.value);await request(`/${page.value}${editID.value?'/'+editID.value:''}`,editID.value?'PUT':'POST',v);editor.value=false;flash('配置已保存并生效');await load()}catch(e:any){error.value=e.message}finally{saving.value=false}}
async function toggle(v:any){try{await request(`/${page.value}/${v.id}`,'PUT',{...v,enabled:!v.enabled});await load()}catch(e:any){error.value=e.message}}
async function action(id:string,type:string){error.value='';try{await request(`/deliveries/${id}/${type}`,'POST',{});flash(type==='replay'?'已创建补投任务，沿用原配置与幂等键':'任务已取消');await load()}catch(e:any){error.value=e.message}}
async function showAttempts(id:string){selectedID.value=id;try{attempts.value=await request(`/deliveries/${id}/attempts`)}catch(e:any){error.value=e.message}}
async function doPreview(){try{const ep=endpoints.value.find(x=>x.id===debugEndpoint.value);if(!ep)throw new Error('请选择目标');preview.value=pretty(await request('/debug/preview','POST',{endpoint:ep,body:sample.value}))}catch(e:any){error.value=e.message}}
async function sendSample(){if(!inject.value)return;try{await request(`/sources/${inject.value}/messages`,'POST',{body:sample.value,dedup_key:''});flash('消息已持久化接收');await load()}catch(e:any){error.value=e.message}}
async function saveCredential(){try{await request('/credentials','POST',{name:credName.value,data:JSON.parse(credData.value)});credName.value='';credData.value='{"secret":""}';flash('凭证已加密保存');await load()}catch(e:any){error.value=e.message}}
function label(id:string,kind:string){return(kind==='source'?sources.value:endpoints.value).find(x=>x.id===id)?.name||id.slice(0,10)}
function date(v:string){return new Date(v).toLocaleString('zh-CN',{hour12:false})}
let timer:ReturnType<typeof setInterval>
onMounted(async()=>{try{await request('/me');authed.value=true;await load()}catch{}finally{checking.value=false};timer=setInterval(()=>{if(!editor.value&&attempts.value===null)load()},5000)})
onUnmounted(()=>clearInterval(timer));watch(page,()=>{query.value='';cursor.value='';error.value='';load()})
</script>

<template>
 <div v-if="checking" class="boot">正在连接 Relay…</div>
 <div v-else-if="!authed" class="login-wrap"><form class="login-card" @submit.prevent="login"><div class="brandmark"><GitBranch :size="24"/></div><div class="eyebrow">MESSAGE DELIVERY PLATFORM</div><h1>连接消息与行动。</h1><p>登录 Relay，管理你的消息转发链路。</p><label>管理员访问令牌<input v-model="token" type="password" autocomplete="current-password" placeholder="输入 RELAY_ADMIN_TOKEN" required></label><div v-if="error" class="error">{{error}}</div><button class="primary" type="submit">进入控制台 <ArrowUpRight :size="16"/></button><div class="login-note"><ShieldCheck :size="14"/>凭证通过服务端会话保护，不保存在浏览器存储</div></form><div class="login-footer">RELAY / CONNECT · TRANSFORM · DELIVER</div></div>
 <div v-else class="shell">
  <aside><a class="brand" @click="router.push('/overview')"><div class="brandmark"><GitBranch :size="22"/></div><span>relay<span class="brand-dot">.</span></span></a><div class="workspace"><div class="workspace-icon"><Database :size="17"/></div><div><strong>消息工作空间</strong><small>默认环境</small></div><span class="online-dot"></span></div><div class="nav-label">工作台</div><nav><RouterLink v-for="n in nav" :key="n.id" :to="'/'+n.id" :class="{active:page===n.id}"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><span v-if="n.id==='deliveries'&&pending" class="nav-count">{{pending}}</span></RouterLink></nav><div class="aside-bottom"><div class="prefix-box"><Settings2 :size="15"/><span>统一前缀 <code>/{{prefix}}</code></span></div><button class="logout" @click="logout"><LogOut :size="16"/>退出会话</button><small>Relay Console <span>v0.1</span></small></div></aside>
  <main><header><div class="breadcrumb">工作台 <ChevronRight :size="13"/><span>{{title}}</span></div><div class="header-right"><span class="environment">● 已连接</span><div class="avatar">A</div></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">{{page==='overview'?'DELIVERY CONTROL CENTER':'RELAY / '+page.toUpperCase()}}</div><h1>{{title}}</h1><p>{{descriptions[page]}}</p></div><div class="heading-actions"><button class="secondary" @click="load" :disabled="loading"><RefreshCw :size="15" :class="{spin:loading}"/>刷新</button><button v-if="['sources','endpoints','routes'].includes(page)" class="primary" @click="newConfig"><Plus :size="16"/>新建{{page==='sources'?'消息源':page==='endpoints'?'目标':'规则'}}</button></div></div>
  <div v-if="error" class="error alert" role="alert">{{error}}<button @click="error=''" aria-label="关闭错误"><X :size="16"/></button></div><div v-if="notice" class="notice" role="status"><Check :size="16"/>{{notice}}</div>
  <template v-if="page==='overview'"><div class="stats"><article><span>累计投递任务<Layers3 :size="17"/></span><strong>{{total.toLocaleString()}}</strong><small>各目标独立计数</small></article><article><span>已成功投递<Check :size="17"/></span><strong class="teal">{{(stats.SUCCEEDED||0).toLocaleString()}}</strong><small>满足目标响应契约</small></article><article><span>等待与处理中<Activity :size="17"/></span><strong>{{pending.toLocaleString()}}</strong><small>持久化队列 · 自动调度</small></article><article><span>完成成功率<ArrowUpRight :size="17"/></span><strong>{{success}}</strong><small>成功 /（成功 + 失败）</small></article></div>
   <section class="panel flow-panel"><div class="section-title"><div><h2>你的转发链路</h2><p>独立接入 · 可靠交接 · 异步投递</p></div><span class="tag gray">架构视图</span></div><div class="flow"><div><div class="flow-icon"><Radio :size="25"/></div><strong>{{sources.filter(x=>x.enabled).length}} 个启用消息源</strong><small>Kafka / RabbitMQ</small></div><span class="flow-line">→</span><div><div class="flow-icon muted"><Database :size="25"/></div><strong>持久化交接</strong><small>事务落库后确认消费</small></div><span class="flow-line">→</span><div><div class="flow-icon"><Webhook :size="25"/></div><strong>{{endpoints.filter(x=>x.enabled).length}} 个启用目标</strong><small>转换 · 签名 · 重试</small></div></div></section>
   <div class="overview-grid"><section class="panel"><div class="section-title"><h2>消息源状态</h2><RouterLink to="/sources" class="text-link">管理消息源 <ArrowUpRight :size="14"/></RouterLink></div><div v-if="!sources.length" class="empty compact"><Radio :size="27"/><strong>还没有消息源</strong><p>连接 Kafka 或 RabbitMQ，开始接收消息。</p><button class="secondary" @click="router.push('/sources')">配置消息源</button></div><div v-for="src in sources.slice(0,5)" :key="src.id" class="source-row"><div class="row-icon"><Radio :size="18"/></div><div><strong>{{src.name}}</strong><small>{{src.type.toUpperCase()}}</small></div><span class="tag" :class="statusTone(states[src.id]?.state||'PAUSED')">{{states[src.id]?.state||'PAUSED'}}</span></div></section><section class="panel"><div class="section-title"><h2>投递分布</h2><span class="tag gray">实时数据</span></div><div class="distribution"><div v-for="[name,value] in Object.entries(stats)" :key="name"><div><span><i :class="statusTone(name)"></i>{{name}}</span><strong>{{value}}</strong></div><div class="bar"><span :style="{width:(total?value/total*100:0)+'%'}"></span></div></div><div v-if="!total" class="empty compact"><Layers3 :size="27"/><strong>等待第一条消息</strong><p>完成来源、目标与规则配置后，这里会显示实际投递数据。</p></div></div></section></div>
  </template>
  <section v-else-if="['sources','endpoints','routes'].includes(page)" class="panel"><div class="table-toolbar"><div class="search"><Search :size="16"/><input v-model="query" placeholder="搜索名称或配置…"></div><small>{{filtered.length}} 项配置</small></div><div v-if="!filtered.length" class="empty"><component :is="page==='sources'?Radio:page==='endpoints'?Webhook:GitBranch" :size="34"/><strong>创建你的第一个{{page==='sources'?'消息源':page==='endpoints'?'Webhook 目标':'转发规则'}}</strong><p>先保存配置，检查参数后再启用。</p><button class="primary" @click="newConfig"><Plus :size="16"/>添加配置</button></div><div v-else class="table-scroll"><table><thead><tr><th>名称 / 标识</th><th>{{page==='sources'?'订阅配置':page==='endpoints'?'请求目标':'来源 → 目标'}}</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="v in filtered" :key="v.id"><td><strong>{{v.name}}</strong><code>{{v.id.slice(0,12)}}</code></td><td v-if="page==='sources'"><span class="type-tag">{{v.type}}</span><small>{{v.topics?.join(', ')||v.queue||'手动测试接入'}}</small></td><td v-else-if="page==='endpoints'"><span class="type-tag">{{v.method}}</span><span class="mono url">{{v.url}}</span><small>{{v.rps}} req/s · {{v.concurrency}} 并发</small></td><td v-else><span>{{label(v.source_id,'source')}}</span><small>→ {{v.endpoint_ids.map((x:string)=>label(x,'endpoint')).join('、')}}</small></td><td><span class="tag" :class="v.enabled?'green':'gray'">{{v.enabled?'已启用':'已暂停'}}</span><small v-if="page==='sources'">{{states[v.id]?.state}}</small></td><td class="right"><button class="text-button" @click="edit(v)">编辑</button><button class="text-button" @click="toggle(v)">{{v.enabled?'暂停':'启用'}}</button></td></tr></tbody></table></div><div class="panel-footer"><ShieldCheck :size="14"/>已接收的消息使用接收时的目标配置，编辑不会改变历史任务。</div></section>
  <section v-else-if="page==='deliveries'" class="panel"><div class="section-title"><h2>最近投递</h2><span class="tag gray">每页最多 100 条</span></div><div v-if="!deliveries.length" class="empty"><Layers3 :size="34"/><strong>暂无投递任务</strong><p>启用消息源与转发规则后，消息会出现在这里。</p></div><div v-else class="table-scroll"><table><thead><tr><th>任务 / 创建时间</th><th>目标</th><th>状态</th><th>尝试</th><th>最近结果</th><th class="right">操作</th></tr></thead><tbody><tr v-for="d in deliveries" :key="d.id"><td><code>{{d.id.slice(0,12)}}</code><small>{{date(d.created_at)}}</small></td><td>{{label(d.endpoint_id,'endpoint')}}</td><td><span class="tag" :class="statusTone(d.status)">{{d.status}}</span></td><td>{{d.attempts}}</td><td class="result-text">{{d.error||'—'}}</td><td class="right"><button class="text-button" @click="showAttempts(d.id)">详情</button><button v-if="['DEAD','SUCCEEDED','CANCELLED'].includes(d.status)" class="text-button" @click="action(d.id,'replay')">补投</button><button v-if="['PENDING','RETRY_WAIT'].includes(d.status)" class="text-button danger" @click="action(d.id,'cancel')">取消</button></td></tr></tbody></table></div><div class="panel-footer pagination"><button class="secondary" @click="cursor='';load()">最新</button><button class="secondary" :disabled="deliveries.length<100" @click="cursor=deliveries.at(-1)?.id||'';load()">下一页</button></div></section>
  <div v-else-if="page==='debug'" class="debug-grid"><section class="panel form-panel"><h2>样例消息</h2><label>消息正文<textarea v-model="sample" class="code-editor" rows="12" spellcheck="false"></textarea></label><label>预览目标<select v-model="debugEndpoint"><option value="">选择目标</option><option v-for="e in endpoints" :key="e.id" :value="e.id">{{e.name}}</option></select></label><button class="primary" @click="doPreview"><Code2 :size="16"/>预览请求</button><div class="hint">纯预览不发送外部请求，也不加载鉴权密钥。</div><hr><label>手动消息源<select v-model="inject"><option value="">选择手动来源</option><option v-for="s in sources.filter(x=>x.type==='manual')" :key="s.id" :value="s.id">{{s.name}}</option></select></label><button class="secondary" :disabled="!inject" @click="sendSample"><Send :size="15"/>接收样例并触发真实转发</button><div class="hint">此操作会持久化消息，并按已启用规则产生真实请求。</div></section><section class="panel preview-panel"><div class="section-title"><h2>请求预览</h2><span class="tag gray">无网络副作用</span></div><pre v-if="preview">{{preview}}</pre><div v-else class="empty"><Terminal :size="32"/><strong>等待生成请求</strong><p>选择目标并预览，检查结构和最终正文。</p></div></section></div>
  <div v-else-if="page==='credentials'" class="debug-grid"><section class="panel form-panel"><h2>创建凭证</h2><label>名称<input v-model="credName" placeholder="例如：合作方签名密钥"></label><label>凭证内容（JSON）<textarea v-model="credData" class="code-editor" rows="10" spellcheck="false"></textarea></label><div class="hint">HMAC：secret；Bearer：token；Basic / Broker：username、password；OAuth2：token_url、client_id、client_secret、scope。</div><button class="primary" @click="saveCredential"><KeyRound :size="15"/>加密保存</button></section><section class="panel"><div class="section-title"><h2>已保存凭证</h2><ShieldCheck :size="17"/></div><div v-if="!credentials.length" class="empty"><KeyRound :size="30"/><strong>暂无凭证</strong><p>凭证原文保存后无法从管理接口读取。</p></div><div v-for="c in credentials" :key="c.id" class="credential-row"><strong>{{c.name}}</strong><code>{{c.id}}</code><small>{{date(c.created_at)}}</small></div></section></div>
  <section v-else-if="page==='audit'" class="panel"><div class="section-title"><h2>最近操作</h2></div><div v-if="!audit.length" class="empty"><ShieldCheck :size="32"/><strong>暂无操作记录</strong></div><table v-else><thead><tr><th>操作</th><th>对象</th><th>时间</th></tr></thead><tbody><tr v-for="(a,i) in audit" :key="i"><td>{{a.action}}</td><td><code>{{a.object_id}}</code></td><td>{{date(a.created_at)}}</td></tr></tbody></table></section>
  <footer class="main-footer"><span>Relay · 让每条消息有迹可循</span><span>消费隔离 / 至少一次投递</span></footer>
  </div></main>
  <div v-if="editor" class="modal-backdrop" @click.self="editor=false"><section class="modal"><div class="section-title"><div><h2>{{editID?'编辑':'新建'}}{{title}}</h2><p>完整配置编辑器 · JSON</p></div><button class="icon-button" @click="editor=false" aria-label="关闭"><X :size="20"/></button></div><div class="modal-body"><div class="hint">来源类型：kafka / rabbitmq / manual。来源连接与订阅创建后不可修改；可修改名称及启用状态。关联 ID 可从列表复制。</div><textarea v-model="json" class="code-editor" rows="22" spellcheck="false" aria-label="配置 JSON"></textarea><div v-if="error" class="error">{{error}}</div></div><div class="modal-footer"><button class="secondary" @click="editor=false">取消</button><button class="primary" :disabled="saving" @click="save">{{saving?'保存中…':'保存配置'}}</button></div></section></div>
  <div v-if="attempts!==null" class="modal-backdrop" @click.self="attempts=null"><section class="modal"><div class="section-title"><div><h2>投递尝试记录</h2><p class="mono">{{selectedID}}</p></div><button class="icon-button" @click="attempts=null" aria-label="关闭"><X :size="20"/></button></div><div class="modal-body"><div v-if="!attempts.length" class="empty"><Activity :size="26"/><strong>等待首次尝试</strong></div><div v-for="a in attempts" :key="a.id" class="attempt"><div><strong>第 {{a.number}} 次</strong><span class="tag" :class="statusTone(a.status)">{{a.status}}</span></div><p>{{a.error||'目标响应符合契约'}}</p><small>HTTP {{a.http_status||'—'}} · {{a.duration_ms}} ms · {{date(a.created_at)}}</small></div></div></section></div>
 </div>
</template>
